INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(982060, 116347, 3080, '<td valign="top">Absolutely LOVE it!!  Crisp, clean, screams music.  Nothing more to say!  Definately a 10.</td>', 'Absolutely LOVE it!!  Crisp, clean, screams music.  Nothing more to say!  Definately a 10.', '2004-11-01 00:03:41.000000', NULL, 1),
(982105, 116719, 22748, '<td valign="top">Nice composition. Only thing I don''t like is that it looks a little oversharpened and noisy.</td>', 'Nice composition. Only thing I don''t like is that it looks a little oversharpened and noisy.', '2004-11-01 00:14:27.000000', NULL, 1),
(982114, 117133, 12253, '<td valign="top">Nice idea--I had the same one myself but fortunately for both of us I didn''t enter or we''d both be dinged for dups.  I was trying to take the CD in a portable player though, and I couldn''t get the reflection right when it was in the player.  Very nice job here!</td>', 'Nice idea--I had the same one myself but fortunately for both of us I didn''t enter or we''d both be dinged for dups.  I was trying to take the CD in a portable player though, and I couldn''t get the reflection right when it was in the player.  Very nice job here!', '2004-11-01 00:16:35.000000', NULL, 1),
(982143, 116719, 20210, '<td valign="top">The lighting could be much more interesting here.  Seems like just a snapshot of a trumpet, the shadows are distracting.  Also, the photo seems pretty grainy for such controlled conditions.  Maybe a concious choice?</td>', 'The lighting could be much more interesting here.  Seems like just a snapshot of a trumpet, the shadows are distracting.  Also, the photo seems pretty grainy for such controlled conditions.  Maybe a concious choice?', '2004-11-01 00:24:30.000000', NULL, 1),
(982156, 117090, 20210, '<td valign="top">This one will need some validation for sure. :)  Very emotive shot.  8.</td>', 'This one will need some validation for sure. :)  Very emotive shot.  8.', '2004-11-01 00:28:33.000000', NULL, 1),
(982162, 117117, 20210, '<td valign="top">A bold shot for this site.  I''m not sure I like it, but you''ll get an extra point from me for going out on a limb with the technique here.</td>', 'A bold shot for this site.  I''m not sure I like it, but you''ll get an extra point from me for going out on a limb with the technique here.', '2004-11-01 00:30:36.000000', NULL, 1),
(982165, 116718, 20210, '<td valign="top">I think could have used even more of this beautiful lighting technique.  I feel like you are very much on the right track with it.  Nice work!</td>', 'I think could have used even more of this beautiful lighting technique.  I feel like you are very much on the right track with it.  Nice work!', '2004-11-01 00:31:51.000000', NULL, 1),
(982169, 116091, 20210, '<td valign="top">I wish you hadn''t used a white shirt.  Against the very bright back wall, that detracts a lot for me.  Otherwise, clever idea, nice execution.</td>', 'I wish you hadn''t used a white shirt.  Against the very bright back wall, that detracts a lot for me.  Otherwise, clever idea, nice execution.', '2004-11-01 00:33:14.000000', NULL, 1),
(982176, 117028, 20210, '<td valign="top">Baton''s aren''t used in piano music; would have been more effective with an orchestral score...but I suppose that''s a technicality.  Otherwise, good angle, pretty good DOF, I wish for a little less glare at the lower-right, distracts from the line of the baton.</td>', 'Baton''s aren''t used in piano music; would have been more effective with an orchestral score...but I suppose that''s a technicality.  Otherwise, good angle, pretty good DOF, I wish for a little less glare at the lower-right, distracts from the line of the baton.', '2004-11-01 00:35:01.000000', NULL, 1),
(982192, 115836, 20210, '<td valign="top">There are too many shadows here for my tastes.  More soft light sources might have helped make this pop like an advertisment photo.</td>', 'There are too many shadows here for my tastes.  More soft light sources might have helped make this pop like an advertisment photo.', '2004-11-01 00:38:06.000000', NULL, 1),
(982198, 116080, 20210, '<td valign="top">very cool idea.  the lighting seems a bit harsh, and I find it eerie that her other arm has gone missing, although maybe that''s intentional to look more like a "human" violin.</td>', 'very cool idea.  the lighting seems a bit harsh, and I find it eerie that her other arm has gone missing, although maybe that''s intentional to look more like a "human" violin.', '2004-11-01 00:39:55.000000', NULL, 1),
(982223, 116799, 20210, '<td valign="top">The title doesn''t add anything in this context for me, but the mood is great, a compelling shot.</td>', 'The title doesn''t add anything in this context for me, but the mood is great, a compelling shot.', '2004-11-01 00:44:35.000000', NULL, 1),
(982229, 115423, 23394, '<td valign="top">nice shot, aznym!  love the emotion!</td>', 'nice shot, aznym!  love the emotion!', '2004-11-01 00:45:54.000000', NULL, 1),
(982254, 117164, 20210, '<td valign="top">I have a hard time getting past what an odd arrangement of tools this is.  Maybe having the bottom of the tuning fork against the guitar body might have been a more indicative shot for tuning than having it stuck in the strings.  Also might have used a little more DOF.</td>', 'I have a hard time getting past what an odd arrangement of tools this is.  Maybe having the bottom of the tuning fork against the guitar body might have been a more indicative shot for tuning than having it stuck in the strings.  Also might have used a little more DOF.', '2004-11-01 00:50:05.000000', NULL, 1),
(982255, 115825, 12694, '<td valign="top">as creepy as this one is, i really like it... the only thing is that the horse should be in front of the keyboard not on it... then it would look more real... if that makes any sense.  and the nightlight is a hotspot.  still, me likes</td>', 'as creepy as this one is, i really like it... the only thing is that the horse should be in front of the keyboard not on it... then it would look more real... if that makes any sense.  and the nightlight is a hotspot.  still, me likes', '2004-11-01 00:50:36.000000', NULL, 1),
(982267, 116764, 20210, '<td valign="top">The lighting needed to be much better to pull this shot off.  I''ve tried this myself a few times on my grand, to no avail.  It''s tough to make effective.  Also, you could have used a lot more DOF for a crisper photo.</td>', 'The lighting needed to be much better to pull this shot off.  I''ve tried this myself a few times on my grand, to no avail.  It''s tough to make effective.  Also, you could have used a lot more DOF for a crisper photo.', '2004-11-01 00:53:06.000000', NULL, 1),
(982344, 116589, 28108, '<td valign="top">Very nice high contrast. The black hair just attracts the eye to the center and then the details below it. Very nice geometry involved. Plus that smile! Very enigmatic... Mona Lisa like... Beautiful, I love it! The only reason I don''t give it a perfect 10 is because I would''ve liked to see nice finger position on the neck... Even if it''s akward (it would''ve added some charm even).</td>', 'Very nice high contrast. The black hair just attracts the eye to the center and then the details below it. Very nice geometry involved. Plus that smile! Very enigmatic... Mona Lisa like... Beautiful, I love it! The only reason I don''t give it a perfect 10 is because I would''ve liked to see nice finger position on the neck... Even if it''s akward (it would''ve added some charm even).', '2004-11-01 01:22:27.000000', NULL, 1),
(982449, 116789, 24459, '<td valign="top">It''s a lovely picture. The only comment I have is you could use some noise-remover. Making this pic smooth would make it even better. After all this is a members challenge. Still I like it a lot</td>', 'It''s a lovely picture. The only comment I have is you could use some noise-remover. Making this pic smooth would make it even better. After all this is a members challenge. Still I like it a lot', '2004-11-01 02:44:09.000000', NULL, 1),
(982451, 115576, 24459, '<td valign="top">I understand the idea of having both - the girls and the ''coyote ugly'' sign in the pic.<br/>Unfortunatelly doing so caused you to leave a great gap in the middle of the pic, which is basicly waisted.<br/>Maybe another angle would help.  5</td>', 'I understand the idea of having both - the girls and the ''coyote ugly'' sign in the pic.Unfortunatelly doing so caused you to leave a great gap in the middle of the pic, which is basicly waisted.Maybe another angle would help.  5', '2004-11-01 02:47:26.000000', NULL, 1),
(982457, 116764, 24459, '<td valign="top">Completely unclear picture. Don''t know what''s on it and it''s completely out of focus.</td>', 'Completely unclear picture. Don''t know what''s on it and it''s completely out of focus.', '2004-11-01 03:09:15.000000', NULL, 1),
(982458, 116127, 24459, '<td valign="top">It''s too small to impress the voters. I would recommend making it bigger in next challenges.<br/>Plus it''s completely out of focus.<br/></td>', 'It''s too small to impress the voters. I would recommend making it bigger in next challenges.Plus it''s completely out of focus.', '2004-11-01 03:10:04.000000', NULL, 1),
(982460, 116944, 24459, '<td valign="top">My winner. Best picture in the whole challenge.<br/>Nothing even comes close. Well done. Hope you Win this one.</td>', 'My winner. Best picture in the whole challenge.Nothing even comes close. Well done. Hope you Win this one.', '2004-11-01 03:10:39.000000', NULL, 1),
(982461, 116589, 24459, '<td valign="top">Great shot. Composition is ideal and contrast is fantastic. I really love the shot. I feel this one is going very high. Well done, and good luck.</td>', 'Great shot. Composition is ideal and contrast is fantastic. I really love the shot. I feel this one is going very high. Well done, and good luck.', '2004-11-01 03:11:29.000000', NULL, 1),
(982463, 116937, 24459, '<td valign="top">The contrast is a bit strong. Maybe making it a bit more pale would result in a bit more dreamy picture as it has some ''memory'' feeling in it.<br/>Still well deserved 9</td>', 'The contrast is a bit strong. Maybe making it a bit more pale would result in a bit more dreamy picture as it has some ''memory'' feeling in it.Still well deserved 9', '2004-11-01 03:13:03.000000', NULL, 1),
(982464, 117090, 24459, '<td valign="top">Beautiful shot, great idea and an impressive presentation. Nothing to add. Great</td>', 'Beautiful shot, great idea and an impressive presentation. Nothing to add. Great', '2004-11-01 03:13:45.000000', NULL, 1),
(982466, 116452, 24459, '<td valign="top">I don''t  like the effect. It add nothing to the pic, and inho is unnecessary.</td>', 'I don''t  like the effect. It add nothing to the pic, and inho is unnecessary.', '2004-11-01 03:14:59.000000', NULL, 1),
(982468, 117026, 24459, '<td valign="top">Great idea and well captured. I really like like this one. It''s so different from all the others. Well done</td>', 'Great idea and well captured. I really like like this one. It''s so different from all the others. Well done', '2004-11-01 03:15:39.000000', NULL, 1),
(982471, 117086, 4267, '<td valign="top">a shell for music?</td>', 'a shell for music?', '2004-11-01 03:18:02.000000', NULL, 1),
(982505, 116091, 24128, '<td valign="top">good pic, you should have done the hair as well :)</td>', 'good pic, you should have done the hair as well :)', '2004-11-01 04:15:20.000000', NULL, 1),
(982510, 116799, 25742, '<td valign="top">satriani never fails</td>', 'satriani never fails', '2004-11-01 04:24:57.000000', NULL, 1),
(982511, 116319, 25742, '<td valign="top">much too busy.</td>', 'much too busy.', '2004-11-01 04:26:39.000000', NULL, 1),
(982513, 117016, 24128, '<td valign="top">nice pic, something seems a little odd around the edges though</td>', 'nice pic, something seems a little odd around the edges though', '2004-11-01 04:29:26.000000', NULL, 1),
(982522, 117132, 27482, '<td valign="top">Very hard to capture (I am positive I couldn´t have done it anyway without SEVERAL trials and error) and it´s a good idea but to me it looks more like you were drawing this in photoshop more than a photo, it´s got that kind of "feel" to it IMO.  I gave it a 7.</td>', 'Very hard to capture (I am positive I couldn´t have done it anyway without SEVERAL trials and error) and it´s a good idea but to me it looks more like you were drawing this in photoshop more than a photo, it´s got that kind of "feel" to it IMO.  I gave it a 7.', '2004-11-01 04:44:47.000000', NULL, 1),
(982523, 117287, 27482, '<td valign="top">It´s a bit soft, but other than that a good shot, nice use of slow shutterspeed.</td>', 'It´s a bit soft, but other than that a good shot, nice use of slow shutterspeed.', '2004-11-01 04:45:50.000000', NULL, 1),
(982524, 117304, 27482, '<td valign="top">Pretty funny shot, I didn´t laugh out loud but it certainly made me smile.  Could it be that these "bikers" were listening to some classical music?</td>', 'Pretty funny shot, I didn´t laugh out loud but it certainly made me smile.  Could it be that these "bikers" were listening to some classical music?', '2004-11-01 04:47:44.000000', NULL, 1),
(982527, 116278, 27482, '<td valign="top">Your WB is way off and I also don´t get the composition, having all that space up in the right upper corner and then cutting off their legs like that.  Pretty poor shot IMO but you seem to have captured the moment pretty well and this certainly meets the challenge, I get a strong sense of "music" here.</td>', 'Your WB is way off and I also don´t get the composition, having all that space up in the right upper corner and then cutting off their legs like that.  Pretty poor shot IMO but you seem to have captured the moment pretty well and this certainly meets the challenge, I get a strong sense of "music" here.', '2004-11-01 04:50:43.000000', NULL, 1),
(982528, 116457, 27482, '<td valign="top">Love her expression.  Also a very good shot, would be surprised to see this below the top 10.</td>', 'Love her expression.  Also a very good shot, would be surprised to see this below the top 10.', '2004-11-01 04:51:56.000000', NULL, 1),
(982529, 117170, 27482, '<td valign="top">Stong image, I love it.  However I think maybe (and just maybe) the light on his face is too little but I am not sure at all if it would improve if you had changed it.</td>', 'Stong image, I love it.  However I think maybe (and just maybe) the light on his face is too little but I am not sure at all if it would improve if you had changed it.', '2004-11-01 04:53:39.000000', NULL, 1),
(982532, 116451, 28097, '<td valign="top">very nice colors.. and the metal shine goes well with the leaves</td>', 'very nice colors.. and the metal shine goes well with the leaves', '2004-11-01 04:58:02.000000', NULL, 1),
(982533, 117086, 28097, '<td valign="top">i have to say, i can relate this picture to sound but not music</td>', 'i have to say, i can relate this picture to sound but not music', '2004-11-01 04:58:35.000000', NULL, 1),
(982534, 116347, 27482, '<td valign="top">Awesome shot, my first 10 in this challenge.  How on earth did you light this shot?  (are those guys wax statues?)</td>', 'Awesome shot, my first 10 in this challenge.  How on earth did you light this shot?  (are those guys wax statues?)', '2004-11-01 05:01:00.000000', NULL, 1),
(982535, 116931, 28097, '<td valign="top">a good idea, not well produced though</td>', 'a good idea, not well produced though', '2004-11-01 05:01:24.000000', NULL, 1),
(982537, 116539, 27482, '<td valign="top">You show excellent control of light and this certainly is an interesting instrument, something out of Africa?  Anyway the best still life shot of an instrument in this challenge but I myself like shots that have action in them better, still a 9 though.</td>', 'You show excellent control of light and this certainly is an interesting instrument, something out of Africa?  Anyway the best still life shot of an instrument in this challenge but I myself like shots that have action in them better, still a 9 though.', '2004-11-01 05:03:24.000000', NULL, 1),
(982538, 115693, 27482, '<td valign="top">Funny!</td>', 'Funny!', '2004-11-01 05:03:40.000000', NULL, 1),
(982539, 116478, 27482, '<td valign="top">Cool door, where is this?</td>', 'Cool door, where is this?', '2004-11-01 05:04:00.000000', NULL, 1),
(982542, 116193, 27482, '<td valign="top">I usually like these high key portraits but this one, I don´t know.  The instrument (don´t know the english word for it) is moving slightly and somewhere the backround is pure white, and somewhere it´s yellowish, it´s like you dodged the backround in photoshop but left out some areas, like over her left shoulder, under her left elbow and at her right thigh.  Good effort though, I love the composition and her expression and this is still better than most shots in this challenge.</td>', 'I usually like these high key portraits but this one, I don´t know.  The instrument (don´t know the english word for it) is moving slightly and somewhere the backround is pure white, and somewhere it´s yellowish, it´s like you dodged the backround in photoshop but left out some areas, like over her left shoulder, under her left elbow and at her right thigh.  Good effort though, I love the composition and her expression and this is still better than most shots in this challenge.', '2004-11-01 05:08:32.000000', NULL, 1),
(982544, 116845, 27482, '<td valign="top">Wow!  I would never have thought of this in a million years, at first I was just wondering where is he/she going with this but then I got it.</td>', 'Wow!  I would never have thought of this in a million years, at first I was just wondering where is he/she going with this but then I got it.', '2004-11-01 05:10:15.000000', NULL, 1),
(982553, 117225, 27482, '<td valign="top">Awesome!  Cant give this anything but a 10, I love the tone and colour in this image.</td>', 'Awesome!  Cant give this anything but a 10, I love the tone and colour in this image.', '2004-11-01 05:18:22.000000', NULL, 1),
(982554, 116931, 27482, '<td valign="top">Good Idea, but poorly executed, IMO you overdid it and it just looks like a big blur.</td>', 'Good Idea, but poorly executed, IMO you overdid it and it just looks like a big blur.', '2004-11-01 05:19:52.000000', NULL, 1),
(982555, 116803, 27482, '<td valign="top">It seems just a little bit out of focus but other than that, a great concert shot.</td>', 'It seems just a little bit out of focus but other than that, a great concert shot.', '2004-11-01 05:20:28.000000', NULL, 1),
(982578, 117012, 24613, '<td valign="top">IMO this is by far the best shot of the challenge!  Perfectly meets the challenge, great subject, focus, and DOF.  Outstanding Job! 10</td>', 'IMO this is by far the best shot of the challenge!  Perfectly meets the challenge, great subject, focus, and DOF.  Outstanding Job! 10', '2004-11-01 05:43:56.000000', NULL, 1),
(982579, 116193, 9073, '<td valign="top">Although this is a nice photo, the hand position is really off-putting. Those who know will be screaming ''get lessons''.</td>', 'Although this is a nice photo, the hand position is really off-putting. Those who know will be screaming ''get lessons''.', '2004-11-01 05:46:02.000000', NULL, 1),
(982584, 117220, 9073, '<td valign="top">The technique of gaussian blur overlays really doesn''t work that well for music, I feel. The music really needs to be sharper.</td>', 'The technique of gaussian blur overlays really doesn''t work that well for music, I feel. The music really needs to be sharper.', '2004-11-01 05:48:06.000000', NULL, 1),
(982586, 116799, 8522, '<td valign="top">OMG, is this Satriani? Damn! Great seat! Nice shot, but I''d have liked to see a more spectacular expression captured, with perhaps a more imaginative composition. The face detail needs to be much sharper.</td>', 'OMG, is this Satriani? Damn! Great seat! Nice shot, but I''d have liked to see a more spectacular expression captured, with perhaps a more imaginative composition. The face detail needs to be much sharper.', '2004-11-01 05:48:34.000000', NULL, 1),
(982589, 115423, 19952, '<td valign="top">This is an excellent photo and the effects you added look great. I hope you gave these guys a copy of the photo! :-) Really nice job.</td>', 'This is an excellent photo and the effects you added look great. I hope you gave these guys a copy of the photo! :-) Really nice job.', '2004-11-01 05:55:32.000000', NULL, 1),
(982595, 116091, 19952, '<td valign="top">Funny! Nice job recreating this shot.</td>', 'Funny! Nice job recreating this shot.', '2004-11-01 06:06:33.000000', NULL, 1),
(982599, 117225, 19952, '<td valign="top">Outstanding macro. I know you kept the DOF shallow on purpose, but I would probably prefer this shot with a deeper focal field. Regardless, it looks great just as you did it. Really nice job.</td>', 'Outstanding macro. I know you kept the DOF shallow on purpose, but I would probably prefer this shot with a deeper focal field. Regardless, it looks great just as you did it. Really nice job.', '2004-11-01 06:14:12.000000', NULL, 1),
(982611, 116752, 18897, '<td valign="top">Excellent! My top pic of the bunch this round. The only thing I don''t really like are the white stripes up on the neck, but I doubt you put them there :-)</td>', 'Excellent! My top pic of the bunch this round. The only thing I don''t really like are the white stripes up on the neck, but I doubt you put them there :-)', '2004-11-01 06:27:06.000000', NULL, 1),
(982619, 116937, 19952, '<td valign="top">This is a really nice product shot. I like the slightly bright lighting and high contrast. Very good job.</td>', 'This is a really nice product shot. I like the slightly bright lighting and high contrast. Very good job.', '2004-11-01 06:38:32.000000', NULL, 1),
(982620, 116368, 18897, '<td valign="top">This is a truly fantastic image! The composition is perfect, nearly dead centered. The washed out skin tones, skillfully induced by the professionally setup muliple light sources and fine-tuned contrast during the post processing. Add to that the tasteful introduction of nipples that really helps adding interest and finally the pure well-focused detail of the player and excellent use of DOF. Magnificent!</td>', 'This is a truly fantastic image! The composition is perfect, nearly dead centered. The washed out skin tones, skillfully induced by the professionally setup muliple light sources and fine-tuned contrast during the post processing. Add to that the tasteful introduction of nipples that really helps adding interest and finally the pure well-focused detail of the player and excellent use of DOF. Magnificent!', '2004-11-01 06:39:33.000000', NULL, 1),
(982625, 117058, 27482, '<td valign="top">I saw a shot smilar to this one and I commented that he overdid it, used a too long shutter and it came out like a big blur.  I feel that the same applies here, but not as much, this shot is better but IMO below average in this challenge.  Good idea though, it´s just the execution I don´t like.  To be clear though I don´t dislike it either.</td>', 'I saw a shot smilar to this one and I commented that he overdid it, used a too long shutter and it came out like a big blur.  I feel that the same applies here, but not as much, this shot is better but IMO below average in this challenge.  Good idea though, it´s just the execution I don´t like.  To be clear though I don´t dislike it either.', '2004-11-01 06:43:44.000000', NULL, 1),
(982628, 115994, 27482, '<td valign="top">Looks like the red channel got overexposed because you can´t make out any details in the lips but good shot.</td>', 'Looks like the red channel got overexposed because you can´t make out any details in the lips but good shot.', '2004-11-01 06:45:26.000000', NULL, 1),
(982633, 116534, 27482, '<td valign="top">Sorry but IMO this is not good, the worst shot in the challenge so far for me and I have gone over about half of them.  Way too much stuff going on in the backround, the microphone is not in focus and also terribly underexposed and I just can´t find anything interesting about the shot.  Sorry if I hurt your feelings but I want to explain why I gave it a 1.  Keep it up though, you can only get better.</td>', 'Sorry but IMO this is not good, the worst shot in the challenge so far for me and I have gone over about half of them.  Way too much stuff going on in the backround, the microphone is not in focus and also terribly underexposed and I just can´t find anything interesting about the shot.  Sorry if I hurt your feelings but I want to explain why I gave it a 1.  Keep it up though, you can only get better.', '2004-11-01 06:47:29.000000', NULL, 1),
(982634, 116761, 27482, '<td valign="top">Perhaps a more interesting backround would nail this shot, if only he had been sitting on a porch somewhere but I love the shot, the softness in it makes it work.</td>', 'Perhaps a more interesting backround would nail this shot, if only he had been sitting on a porch somewhere but I love the shot, the softness in it makes it work.', '2004-11-01 06:48:26.000000', NULL, 1),
(982636, 116091, 28097, '<td valign="top">a very nice idea.. but photo quality is not so good</td>', 'a very nice idea.. but photo quality is not so good', '2004-11-01 06:49:12.000000', NULL, 1),
(982639, 116069, 27482, '<td valign="top">Well it is a vinyl, no doubt about that but it´s very hard to make out, it´s awfully dark, not neccesarily a problem for a shot but in this instance, it´s not a benefit.</td>', 'Well it is a vinyl, no doubt about that but it´s very hard to make out, it´s awfully dark, not neccesarily a problem for a shot but in this instance, it´s not a benefit.', '2004-11-01 06:53:08.000000', NULL, 1),
(982640, 116080, 27482, '<td valign="top">Good idea, I bet you find her inspiring.</td>', 'Good idea, I bet you find her inspiring.', '2004-11-01 06:55:09.000000', NULL, 1),
