(982675, 116511, 14614, '<td valign="top">like the twist on having the notes go from black to whitish gray.  Something odd about the bBackground  -- don''t know quite what but it detracts somehow.</td>', 'like the twist on having the notes go from black to whitish gray.  Something odd about the bBackground  -- don''t know quite what but it detracts somehow.', '2004-11-01 07:15:33.000000', NULL, 1),
(982784, 116566, 6130, '<td valign="top">I love it.10</td>', 'I love it.10', '2004-11-01 09:07:13.000000', NULL, 1),
