(983550, 117294, 20779, '<td valign="top">A favorite band of mine. Great moment caught. His face lost a lot of detail due to the blown highlights unfortunately.</td>', 'A favorite band of mine. Great moment caught. His face lost a lot of detail due to the blown highlights unfortunately.', '2004-11-01 15:05:07.000000', NULL, 1),
(983554, 116417, 24846, '<td valign="top">Good representation of today''s playnack technology. Although it probably shouldn''t, I find the 512mb label distracting. Great shadows, dof, and cropping.</td>', 'Good representation of today''s playnack technology. Although it probably shouldn''t, I find the 512mb label distracting. Great shadows, dof, and cropping.', '2004-11-01 15:06:12.000000', NULL, 1),
(983556, 115994, 20779, '<td valign="top">Very good work done with the tight focus. The overall image is slightly imbalanced for me. The mike is heavy and dark and her lips have a very light tonal range with a delicate feel. Focus is crisp and clean, and editing excellent.</td>', 'Very good work done with the tight focus. The overall image is slightly imbalanced for me. The mike is heavy and dark and her lips have a very light tonal range with a delicate feel. Focus is crisp and clean, and editing excellent.', '2004-11-01 15:06:24.000000', NULL, 1),
