(985504, 116067, 14614, '<td valign="top">I like the low key B&amp;W - wood grain really stands out and becomes an interesting element.  Showing just enough of the instrument and case to tell the "gone by" story.  One of my ribbon choices this challenge.</td>', 'I like the low key B&W - wood grain really stands out and becomes an interesting element.  Showing just enough of the instrument and case to tell the "gone by" story.  One of my ribbon choices this challenge.', '2004-11-02 08:28:34.000000', NULL, 1),
(985510, 116589, 14614, '<td valign="top">Like the duo-tone effect you''ve created -- very punch darks and nice high key effects.  I feel the crop is a bit tight on the bottom.  As presented, one of my favorites this challenge</td>', 'Like the duo-tone effect you''ve created -- very punch darks and nice high key effects.  I feel the crop is a bit tight on the bottom.  As presented, one of my favorites this challenge', '2004-11-02 08:30:20.000000', NULL, 1),
