(996669, 115975, 1202, '<td valign="top">I think you needed just a bit more depth of field to include sharp focus on the formost part of the horn. Nice otherwise.  6</td>', 'I think you needed just a bit more depth of field to include sharp focus on the formost part of the horn. Nice otherwise.  6', '2004-11-07 10:04:54.000000', NULL, 1),
