(996899, 116944, 14453, '<td valign="top">My favorite of the challenge.  Wonderful expression.  A perfect balance of sharpness and softness.  Good luck!  10</td>', 'My favorite of the challenge.  Wonderful expression.  A perfect balance of sharpness and softness.  Good luck!  10', '2004-11-07 14:04:26.000000', NULL, 1),
(996901, 116803, 2337, '<td valign="top">Shooting in a club is very difficult.  The background behind the singer hurts a bit... For a club shot in a challenge, I''ve found closeups of one band member tend to work better.  But that''s just me, and what do I know :)</td>', 'Shooting in a club is very difficult.  The background behind the singer hurts a bit... For a club shot in a challenge, I''ve found closeups of one band member tend to work better.  But that''s just me, and what do I know :)', '2004-11-07 14:05:23.000000', NULL, 1),
