(997020, 115423, 7504, '<td valign="top">I like the high contrast here, and the expression on the guys face is awesome!  Very nice journalistic feel to this.</td>', 'I like the high contrast here, and the expression on the guys face is awesome!  Very nice journalistic feel to this.', '2004-11-07 15:42:22.000000', NULL, 1),
