(1063454, 115994, 23458, '<td valign="top">I think this would have worked better with just the lips and the microphone - you might have offended some with the potentially overt sexual connotations but the presence of the nose detracts from an otherwise extremely accomplished shot. <br/> <br/></td>', 'I think this would have worked better with just the lips and the microphone - you might have offended some with the potentially overt sexual connotations but the presence of the nose detracts from an otherwise extremely accomplished shot.  ', '2004-12-15 03:28:23.000000', NULL, 0),
(1077087, 116752, 29721, '<td valign="top">great shot.</td>', 'great shot.', '2004-12-25 13:54:51.000000', NULL, 0),
(1100742, 116768, 31865, '<td valign="top">That''s a great photo!  The strange thing is, this is my dad!  He was googling his band and came across this page and emailed it to me.  I''m glad he did because I''m a photographer and this seems like a cool site.  Anyway, once again, really nice photo.  I love the contrast.  Very nice tones.  And great subject matter, but I''m kind of biased. :)</td>', 'That''s a great photo!  The strange thing is, this is my dad!  He was googling his band and came across this page and emailed it to me.  I''m glad he did because I''m a photographer and this seems like a cool site.  Anyway, once again, really nice photo.  I love the contrast.  Very nice tones.  And great subject matter, but I''m kind of biased. :)', '2005-01-10 22:30:28.000000', NULL, 0),
(1100875, 116768, 19708, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by utro:</b></div><hr/><i> That''s a great photo!  The strange thing is, this is my dad! </i></td></tr></table> <br/>That is an incedible twist in a challenge shot here on DPC. Way cool!<br/>Small world.</td>', 'Originally posted by utro: That''s a great photo!  The strange thing is, this is my dad!  That is an incedible twist in a challenge shot here on DPC. Way cool!Small world.', '2005-01-11 00:43:52.000000', NULL, 0),
(1132244, 116690, 656, '<td valign="top">Another fine shot that could be tightened up with a crop.  I''d go almost square with this one, just above the start of the stage at the bottom, and down maybe to the green spotlight from the top.  Suddenly I find myself more involved, closer to the stage, engaged.  The colours are great - very colourful and well captured in such low light.  The guitarist in the foreground appears a bit smooth skinned (neat image again ?)</td>', 'Another fine shot that could be tightened up with a crop.  I''d go almost square with this one, just above the start of the stage at the bottom, and down maybe to the green spotlight from the top.  Suddenly I find myself more involved, closer to the stage, engaged.  The colours are great - very colourful and well captured in such low light.  The guitarist in the foreground appears a bit smooth skinned (neat image again ?)', '2005-01-26 00:19:46.000000', NULL, 0),
(1170265, 116589, 5728, '<td valign="top">I can''t believe I never saw this. It''s a wonderful image. Congrats on the ribbon!</td>', 'I can''t believe I never saw this. It''s a wonderful image. Congrats on the ribbon!', '2005-02-15 01:16:35.000000', NULL, 0),
